intmax_t imax = 1;
size_t sz = 20;
uint64_t u64 = 0xDEADBEEF;
long double ld_val = 3.14L;
char c_arr[] = "Test";

// Required Macros and Specifiers
printf("Max: %" PRIdMAX "\n", imax);
printf("Size: %zu\n", sz);
printf("U64: %" PRIX64 "\n", u64);

// Standard Promotions: float -> double
float f_val = 1.0f;
printf("F: %f\n", f_val); // %f for promoted double

// Long Double (LDBL_MAX)
printf("LD: %Le\n", ld_val);

// String precision/width control
printf("Str: %10.3s\n", c_arr);

// %n (write count of chars written so far)
int chars_written;
printf("Count here%n", &chars_written);
